package com.oms.order.service;

import com.ruoyi.common.core.domain.R;
import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.order.service.OrderValues.*;

class OrderShipmentReceiptServiceTest {
    OrderShipmentDispatchServiceTest f=new OrderShipmentDispatchServiceTest();OrderShipmentReceiptService service;long line;
    @BeforeAll static void start(){OrderShipmentDispatchServiceTest.setup();}
    @BeforeEach void seed(){f.seed();f.create(10);f.submit(1);f.dispatch.process("VERIFY",f.shipment);line=f.fixture.db.queryForObject("SELECT id FROM oms_order_shipment_line",Long.class);service=new OrderShipmentReceiptService();ReflectionTestUtils.setField(service,"repository",f.fixture.repository);ReflectionTestUtils.setField(service,"locks",f.dispatch);ReflectionTestUtils.setField(service,"wms",f.wms);ReflectionTestUtils.setField(service,"inventory",f.inventory);when(f.inventory.warehouseReceipt(anyString(),anyString(),anyString())).thenReturn(R.ok(row("state","MISSING")));when(f.inventory.warehouseOutbound(anyString(),anyMap(),anyString())).thenAnswer(i->R.ok(((Map<?,?>)i.getArgument(1)).containsKey("lines")?reply(i.getArgument(1)):row()));when(f.wms.receiptResult(anyString(),anyLong(),anyMap(),anyString())).thenReturn(R.ok(true));}
    Map<String,Object> row(Object...pairs){return f.row(pairs);}
    Map<String,Object> event(long id,long quantity,boolean complete){Map<String,Object> receipt=row("shipment_id",f.shipment,"shipment_sn",f.document().get("shipment_sn"),"task_id",77,"original_payload_hash",f.intent().get("payload_hash"),"external_order","WMS-77","external_warehouse","EXT-W","external_owner","EXT-O","message_id","MESSAGE"+id,"final_confirmation",complete?1:0,"outbound_time","2026-10-12 12:00:00","warehouse_status",complete?"DELIVERED":"PARTDELIVERED","quantity",quantity,"lines",quantity==0?Collections.emptyList():Arrays.asList(row("id",line,"sku_sn","A","batch_code","B001","quantity",quantity)),"packages",quantity==0?Collections.emptyList():Arrays.asList(row("package_code","PACKAGE"+id,"express_code","TEST-WMS-"+id,"warehouse_carrier_code","SF","lines",Arrays.asList(row("id",line,"sku_sn","A","quantity",quantity)))));return row("id",id,"payload",receipt);}
    @SuppressWarnings("unchecked") Map<String,Object> reply(Map<String,Object> command){List<Map<String,Object>> lines=new ArrayList<>();for(Map<String,Object> old:(List<Map<String,Object>>)command.get("lines")){Map<String,Object> line=new LinkedHashMap<>(old);line.put("outbound_quantity",number(old,"outbound_before")+number(old,"quantity"));lines.add(line);}return row("state","COMPLETED","source_mode","WMS","request_id",command.get("request_id"),"shipment_sn",command.get("shipment_sn"),"quantity",command.get("quantity"),"lines",lines);}
    Map<String,Object> task(){return f.fixture.db.queryForMap("SELECT * FROM oms_order_shipment_outbound ORDER BY id DESC LIMIT 1");}
    Map<String,Object> detail(){return f.fixture.service.detail("VERIFY",f.shipment);}
    @Test void partialThenFullPostsInventoryAndParcelsExactlyOnce(){Map<String,Object> first=event(1001,4,false);assertEquals(true,service.process("VERIFY",first,false,"test").get("success"));assertEquals("PART_SHIPPED",detail().get("status"));assertEquals(4,number(detail(),"shipped_quantity"));assertEquals(4,number(detail(),"packaged_quantity"));assertEquals(0,number(detail(),"unpacked_quantity"));assertEquals(1,number(detail(),"package_count"));assertEquals(true,service.process("VERIFY",first,false,"test").get("success"));verify(f.inventory,times(1)).warehouseOutbound(anyString(),anyMap(),anyString());assertEquals(true,service.process("VERIFY",event(1002,6,true),false,"test").get("success"));assertEquals("SHIPPED",detail().get("status"));assertEquals(10,number(detail(),"shipped_quantity"));assertEquals(2,number(detail(),"package_count"));assertEquals("SHIPPED",f.fixture.summary().get("business_status"));assertEquals(10,number(f.fixture.summary(),"warehouse_outbound_quantity"));assertEquals(10,f.fixture.db.queryForObject("SELECT reserved_quantity FROM oms_order_line",Integer.class));}
    @Test void lostInventoryReplyReconcilesOriginalReceiptWithoutPostingAgain(){Map<String,Object>[] committed=new Map[1];doAnswer(i->{committed[0]=reply(i.getArgument(1));throw new IllegalStateException("lost");}).when(f.inventory).warehouseOutbound(anyString(),anyMap(),anyString());Map<String,Object> event=event(1010,4,false);assertEquals("UNKNOWN",service.process("VERIFY",event,false,"test").get("state"));assertEquals(0,number(detail(),"shipped_quantity"));when(f.inventory.warehouseReceipt(anyString(),anyString(),anyString())).thenAnswer(i->R.ok(committed[0]));assertEquals(true,service.process("VERIFY",event,true,"test").get("success"));verify(f.inventory,times(1)).warehouseOutbound(anyString(),anyMap(),anyString());assertEquals(4,number(detail(),"shipped_quantity"));}
    @Test void definitiveStockFailureRetriesSameCommandBeforeFollowingEvent(){doReturn(R.fail("source mismatch")).when(f.inventory).warehouseOutbound(anyString(),anyMap(),anyString());Map<String,Object> first=event(1020,4,false);assertEquals("FAILED",service.process("VERIFY",first,false,"test").get("state"));assertEquals(0,number(detail(),"shipped_quantity"));String json=text(task(),"payload_json");assertThrows(IllegalArgumentException.class,()->service.process("VERIFY",event(1021,6,true),false,"test"));doAnswer(i->R.ok(reply(i.getArgument(1)))).when(f.inventory).warehouseOutbound(anyString(),anyMap(),anyString());assertEquals(true,service.process("VERIFY",first,true,"test").get("success"));assertEquals(json,task().get("payload_json"));assertEquals(true,service.process("VERIFY",event(1021,6,true),false,"test").get("success"));assertEquals(10,number(detail(),"shipped_quantity"));}
    @Test void malformedStockReplyRollsBackAllLocalProgressAndPackages(){doAnswer(i->{Map<String,Object> reply=reply(i.getArgument(1));((List<Map<String,Object>>)reply.get("lines")).add(row("id",999));return R.ok(reply);}).when(f.inventory).warehouseOutbound(anyString(),anyMap(),anyString());assertEquals("UNKNOWN",service.process("VERIFY",event(1030,4,false),false,"test").get("state"));assertEquals(0,number(detail(),"shipped_quantity"));assertEquals(0,number(detail(),"package_count"));assertEquals("UNKNOWN",task().get("state"));}
    @Test void parcelMismatchUnknownCarrierAndOtherTenantCannotConsume(){Map<String,Object> bad=event(1040,4,false);((Map<String,Object>)((List<?>)((Map<?,?>)bad.get("payload")).get("packages")).get(0)).put("warehouse_carrier_code","UNKNOWN");assertThrows(IllegalArgumentException.class,()->service.process("VERIFY",bad,false,"test"));assertThrows(IllegalArgumentException.class,()->service.process("OTHER",event(1041,4,false),false,"test"));assertEquals(0,number(detail(),"shipped_quantity"));verify(f.inventory,never()).warehouseOutbound(anyString(),anyMap(),anyString());}
    @Test void heldOrderStillRecordsVerifiedPhysicalFactAndWarehouseQueryCannotRegressShipping(){f.fixture.db.update("UPDATE oms_order SET manual_hold=1");assertEquals(true,service.process("VERIFY",event(1050,10,true),false,"test").get("success"));f.dispatch.query("VERIFY",f.shipment,"test");assertEquals("SHIPPED",detail().get("status"));assertEquals(10,number(detail(),"shipped_quantity"));assertEquals(false,f.fixture.summary().get("can_void"));}
    @Test void finalNoticeWithRemainderNeverFakesFullDelivery(){service.process("VERIFY",event(1060,4,false),false,"test");assertEquals(true,service.process("VERIFY",event(1061,0,true),false,"test").get("success"));assertEquals("PART_SHIPPED",detail().get("status"));assertEquals(4,number(detail(),"shipped_quantity"));assertEquals(6,number(f.fixture.summary(),"warehouse_occupied_quantity"));verify(f.inventory,times(1)).warehouseOutbound(anyString(),anyMap(),anyString());}
    @Test void warehouseAckLostAfterCommitOnlyRetriesAck(){doThrow(new IllegalStateException("lost ack")).when(f.wms).receiptResult(anyString(),anyLong(),anyMap(),anyString());Map<String,Object> first=event(1070,4,false);assertEquals(true,service.process("VERIFY",first,false,"test").get("ack_pending"));assertEquals(true,service.process("VERIFY",first,false,"test").get("success"));verify(f.inventory,times(1)).warehouseOutbound(anyString(),anyMap(),anyString());assertEquals(4,number(detail(),"packaged_quantity"));}
}
